"""MD&A-style commentary generated by Claude from the computed figures.

Claude only sees the numbers this package already extracted and computed, and
is told to use nothing else, so every figure in the commentary ties back to
the workbook.
"""

from __future__ import annotations

import json
import os

from isviz import analysis
from isviz.statements import IncomeStatement

DEFAULT_MODEL = "claude-opus-5-5"

SYSTEM_PROMPT = """\
You are a senior financial analyst writing the results-of-operations section \
of an MD&A-style memo for a reviewer at an accounting firm.

Use only the figures in the JSON you are given. Don't bring in outside facts \
about the company, guidance, or market events, since the reader will tie every \
number back to the source workbook. If a driver can't be determined from the \
data, say so instead of speculating.

Write 3-5 short paragraphs of plain prose with no headings or bullet points. \
Cover revenue trend and growth, margin movement (gross, operating, net), the \
effective tax rate, and anything a reviewer should look into. Express dollars \
in billions or millions with one decimal place and percentages to one decimal \
place. If `restated_items` is not empty, point out that those values changed \
between filings and that a stock split is a common cause for EPS."""


class NarrativeError(RuntimeError):
    pass


def generate(stmt: IncomeStatement, model: str | None = None) -> str:
    try:
        import anthropic
    except ImportError as exc:
        raise NarrativeError("Install the AI extra: pip install 'isviz[ai]'") from exc

    payload = analysis.summary(stmt)
    payload["history"] = {
        str(fy): {k: (None if v != v else v) for k, v in row.items()}  # NaN -> None
        for fy, row in stmt.data.to_dict(orient="index").items()
    }
    payload["margin_history"] = {
        str(fy): {k: (None if v != v else round(v, 4)) for k, v in row.items()}
        for fy, row in analysis.margins(stmt).to_dict(orient="index").items()
    }

    client = anthropic.Anthropic()
    try:
        response = client.beta.messages.create(
            model=model or os.environ.get("ISVIZ_MODEL", DEFAULT_MODEL),
            max_tokens=16000,
            system=SYSTEM_PROMPT,
            output_config={"effort": "medium"},
            # If the primary model declines, the API retries on a fallback model.
            betas=["server-side-fallback-2026-07-01"],
            fallbacks="default",
            messages=[
                {
                    "role": "user",
                    "content": "Write the commentary for this company:\n\n"
                    + json.dumps(payload, indent=2),
                }
            ],
        )
    except anthropic.AuthenticationError as exc:
        raise NarrativeError(
            "Anthropic credentials missing or invalid (ANTHROPIC_API_KEY)."
        ) from exc
    except anthropic.RateLimitError as exc:
        raise NarrativeError("Rate limited by the Anthropic API; try again shortly.") from exc
    except anthropic.APIStatusError as exc:
        raise NarrativeError(f"Anthropic API error {exc.status_code}: {exc.message}") from exc
    except anthropic.APIConnectionError as exc:
        raise NarrativeError("Could not reach the Anthropic API.") from exc

    if response.stop_reason == "refusal":
        raise NarrativeError("The model declined to generate commentary for this request.")
    text = "".join(b.text for b in response.content if b.type == "text").strip()
    if not text:
        raise NarrativeError(f"Empty response (stop_reason={response.stop_reason}).")
    return text
